#!/usr/bin/env python3
"""
Round 135b (culprits), 2 October 2026. Needs round 134b.

Reefs drawn smooth in teal; the food industry map whole.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 135b (2 October)\n\nNeeds round 134b. Tiles patch round135b_tiles.py beside it. No app.js?v= bump.\n\n- Reefs (allen_coral): the world view no longer reads as white squares\n  (asked 2 October). UNEP-WCMC's picture is asked at full size (256, was\n  96 stretched with nearest-neighbour), drawn smoothed, in the map's light\n  teal 6FC2DA (was bone E3D2CC), still grown a pixel or two so small reefs\n  show.\n- Who Owns the Food Industry: the row reads food/system.places.geojson (tiles\n  food_system.py), the page's whole data: 48 companies (sector, revenue,\n  share of the page's $12 trillion system, ownership, HQ, brands, regional\n  sites), 8 asset managers and financiers, 5 lobby groups, 12 orbit bodies,\n  and 191 tie lines (shareholdings, lobby membership, orbit ties); each\n  company's box lists who holds it, its lobby groups and its orbit ties. The\n  tiles patch carries a first build.\n\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round135b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 134b" not in h.read_text(encoding="utf-8"):
        sys.exit("round135b: round 134b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round135b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round135b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round135b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
